Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <algorithm>

#define MAXN 1100000
#define MOD 1000000007

using namespace std;

typedef long long int LL;

LL p,K;

LL fastPow(LL base,LL pow)
{
    LL ans=1;
    while(pow)
    {
        if(pow&1) ans=(ans*base)%MOD;
        base=(base*base)%MOD;
        pow>>=1;
    }
    return ans;
}

bool vis[MAXN];

int main()
{
    scanf("%I64d%I64d",&p,&K);
    if(K==0)
    {
        printf("%I64d\n",fastPow(p,p-1));
        return 0;
    }
    else if(K==1)
    {
        printf("%I64d\n",fastPow(p,p));
        return 0;
    }
    int cnt=0;
    for(int i=0;i<p;i++)
    {
        if(vis[i]) continue;
        int size=0;
        LL tmp=i;
        while(!vis[tmp])
        {
            size++;
            vis[tmp]=true;
            tmp=tmp*K%p;
        }
        if(size>1) cnt++;
    }
    printf("%I64d\n",fastPow(p,cnt));
    return 0;
}
</original_code>
